    # Identify full-width divider rows and full-height divider columns.
    sep = next(v for v in set(sum(grid, []))
               if any(all(x == v for x in row) for row in grid)
               or any(all(grid[r][c] == v for r in range(h)) for c in range(w)))
    row_bars = [r for r, row in enumerate(grid) if all(x == sep for x in row)]
    col_bars = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    # Copy cells by reflection across the appropriate dividers; if a cell on
    # one side is occupied and its mirror is blank, fill the mirrored cell.
    for b in row_bars:
        for d in range(1, 4):
            for src in (b - d, b + d):
                dst = 2 * b - src
                if 0 <= src < h and 0 <= dst < h:
                    for c, v in enumerate(grid[src]):
                        if v not in (0, sep) and grid[dst][c] == 0:
                            out[dst][c] = v
    for b in col_bars:
        for d in range(1, 4):
            for src in (b - d, b + d):
                dst = 2 * b - src
                if 0 <= src < w and 0 <= dst < w:
                    for r in range(h):
                        v = grid[r][src]
                        if v not in (0, sep) and grid[r][dst] == 0:
                            out[r][dst] = v
    return out
